// Secure Express.js application with comprehensive error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet()); // Sets various security headers
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || 'http://localhost:3000',
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateHealthCheck = (req, res, next) => {
  const { detailed } = req.query;

  if (detailed && !['true', 'false'].includes(detailed)) {
    return res.status(400).json({
      error: 'Invalid parameter',
      message: 'detailed must be either "true" or "false"'
    });
  }

  next();
};

const validateUsersQuery = (req, res, next) => {
  const { limit, offset } = req.query;

  // Validate limit parameter
  if (limit) {
    const limitNum = parseInt(limit);
    if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({
        error: 'Invalid parameter',
        message: 'limit must be a number between 1 and 100'
      });
    }
  }

  // Validate offset parameter
  if (offset) {
    const offsetNum = parseInt(offset);
    if (isNaN(offsetNum) || offsetNum < 0) {
      return res.status(400).json({
        error: 'Invalid parameter',
        message: 'offset must be a non-negative number'
      });
    }
  }

  next();
};

// Routes with validation
app.get('/health', validateHealthCheck, (req, res) => {
  try {
    const { detailed } = req.query;
    const response = { 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    if (detailed === 'true') {
      response.memoryUsage = process.memoryUsage();
      response.env = process.env.NODE_ENV;
    }

    res.json(response);
  } catch (error) {
    res.status(500).json({
      error: 'Internal server error',
      message: 'Unable to process health check request'
    });
  }
});

app.get('/users', validateUsersQuery, (req, res) => {
  try {
    const { limit = 10, offset = 0 } = req.query;
    const limitNum = parseInt(limit);
    const offsetNum = parseInt(offset);

    // Sample user data (in production, this would come from a database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'admin' }
    ];

    // Apply pagination
    const users = allUsers.slice(offsetNum, offsetNum + limitNum);

    // Sanitize response - don't expose sensitive information
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      role: user.role
      // Email is intentionally omitted for security
    }));

    res.json({
      users: sanitizedUsers,
      pagination: {
        total: allUsers.length,
        limit: limitNum,
        offset: offsetNum,
        hasMore: offsetNum + limitNum < allUsers.length
      }
    });
  } catch (error) {
    console.error('Error in users endpoint:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Unable to retrieve users'
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't leak error details in production
  if (process.env.NODE_ENV === 'production') {
    res.status(500).json({
      error: 'Internal server error',
      message: 'Something went wrong'
    });
  } else {
    res.status(500).json({
      error: error.name || 'Internal server error',
      message: error.message,
      stack: error.stack
    });
  }
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running securely on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

