      return res.status(400).json({
        error: 'Invalid page parameter',
        message: 'Page must be a positive integer'
      });
    }
  }

  if (req.query.limit) {
    const limit = parseInt(req.query.limit);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter', 
        message: 'Limit must be between 1 and 100'
      });
    }
  }

  next();
};

// 2. Enhanced Health Endpoint with Error Handling
app.get('/health', (req, res) => {
  try {
    // Validate any incoming parameters
    if (req.query.detailed) {
      const detailed = req.query.detailed.toLowerCase();
      if (detailed !== 'true' && detailed !== 'false') {
        return res.status(400).json({
          error: 'Invalid parameter',
          message: 'detailed must be true or false'
        });
      }
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to process health check'
    });
  }
});

