// Improved application with security best practices and error handling
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || 'http://localhost:3000',
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'Something went wrong'
  });
});

// Health endpoint with input validation
app.get('/health', [
  // Add any query parameter validation if needed
], (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      error: 'Health check failed'
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if any
    const { limit, offset } = req.query;

    if (limit && (!Number.isInteger(Number(limit)) || Number(limit) < 1)) {
      return res.status(400).json({
        error: 'Invalid limit parameter - must be a positive integer'
      });
    }

    if (offset && (!Number.isInteger(Number(offset)) || Number(offset) < 0)) {
      return res.status(400).json({
        error: 'Invalid offset parameter - must be a non-negative integer'
      });
    }

    // Sanitize response data
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        created: new Date('2023-01-01').toISOString()
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        created: new Date('2023-01-02').toISOString()
      },
    ];

    res.json({
      success: true,
      data: users,
      metadata: {
        count: users.length,
        timestamp: new Date().toISOString()
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      success: false,
      error: 'Failed to retrieve users',
      message: process.env.NODE_ENV === 'development' ? error.message : 'Internal server error'
    });
  }
});

// Example POST endpoint with validation
app.post('/users', [
  body('name').trim().isLength({ min: 1, max: 100 }).withMessage('Name must be between 1-100 characters'),
  body('email').isEmail().normalizeEmail().withMessage('Valid email is required'),
], (req, res) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        success: false,
        errors: errors.array()
      });
    }

    // Process valid data
    const { name, email } = req.body;

    // Sanitize and validate input further if needed

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: { id: Date.now(), name, email }
    });

  } catch (error) {
    console.error('Create user error:', error);
    res.status(500).json({
      success: false,
      error: 'Failed to create user'
    });
  }
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    success: false,
    error: 'Endpoint not found',
    path: req.originalUrl
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

