// Improved application with proper error handling and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// CORS configuration
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Request logging
app.use(morgan('combined'));

// Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({
      error: 'Invalid JSON payload',
      message: 'Please check your request body format'
    });
  }

  res.status(500).json({
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' 
      ? 'Something went wrong' 
      : err.message
  });
});

// Request validation middleware
const validateRequest = (schema) => (req, res, next) => {
  const { error } = schema.validate(req.query || req.body || req.params);
  if (error) {
    return res.status(400).json({
      error: 'Validation failed',
      details: error.details.map(detail => ({
        message: detail.message,
        field: detail.path.join('.')
      }))
    });
  }
  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Health check failed',
      status: 'error'
    });
  }
});

// User ID validation schema (using Joi for example)
const userIdSchema = {
  id: Joi.number().integer().min(1).required()
};

// Users endpoint with improved error handling
app.get('/users', (req, res) => {
  try {
    // Input validation for query parameters
    const { limit, offset } = req.query;

    if (limit && (!Number.isInteger(Number(limit)) || Number(limit) < 1 || Number(limit) > 100)) {
      return res.status(400).json({
        error: 'Invalid limit parameter',
        message: 'Limit must be an integer between 1 and 100'
      });
    }

    if (offset && (!Number.isInteger(Number(offset)) || Number(offset) < 0)) {
      return res.status(400).json({
        error: 'Invalid offset parameter',
        message: 'Offset must be a non-negative integer'
      });
    }

    // Mock data (in real app, this would come from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if parameters provided
    const result = {
      users: users,
      total: users.length,
      limit: limit ? Number(limit) : null,
      offset: offset ? Number(offset) : null
    };

    // Security: Set proper headers
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Frame-Options', 'DENY');

    res.json(result);

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Failed to retrieve users',
      message: process.env.NODE_ENV === 'production' 
        ? 'Internal server error' 
        : error.message
    });
  }
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

// Start server with error handling
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
}).on('error', (err) => {
  if (err.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
    process.exit(1);
  } else {
    console.error('Server failed to start:', err);
    process.exit(1);
  }
});

module.exports = { app, server };

// Validation schemas using Joi
const Joi = require('joi');

const userSchema = Joi.object({
  id: Joi.number().integer().min(1).required(),
  name: Joi.string().min(1).max(100).required(),
  email: Joi.string().email().max(255).required(),
  age: Joi.number().integer().min(0).max(150).optional(),
  role: Joi.string().valid('user', 'admin', 'moderator').default('user')
});

const queryParamsSchema = Joi.object({
  limit: Joi.number().integer().min(1).max(100).default(10),
  offset: Joi.number().integer().min(0).default(0),
  sortBy: Joi.string().valid('name', 'email', 'id').default('id'),
  sortOrder: Joi.string().valid('asc', 'desc').default('asc')
});

const userIdSchema = Joi.object({
  id: Joi.number().integer().min(1).required()
});

module.exports = {
  userSchema,
  queryParamsSchema,
  userIdSchema
};

# Security Best Practices for Express Applications

## Authentication & Authorization

### 1. Use Strong Session Management
```javascript
const session = require('express-session');
app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: process.env.NODE_ENV === 'production',
    httpOnly: true,
    maxAge: 24 * 60 * 60 * 1000 // 24 hours
  }
}));
```

### 2. Implement Rate Limiting
```javascript
const rateLimit = require('express-rate-limit');
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per window
  message: 'Too many login attempts',
  skipSuccessfulRequests: true
});
app.use('/login', authLimiter);
```

## Input Validation & Sanitization

### 3. Validate All Inputs
```javascript
// Using Joi for validation
const userSchema = Joi.object({
  email: Joi.string().email().required(),
  password: Joi.string().min(8).pattern(/[a-z]/).pattern(/[A-Z]/)
    .pattern(/\d/).pattern(/[!@#$%^&*]/).required()
});
```

### 4. Sanitize User Input
```javascript
const xss = require('xss');
const sanitizeInput = (input) => {
  return typeof input === 'string' ? xss(input.trim()) : input;
};
```

## Secure Headers & CORS

### 5. Use Helmet.js
```javascript
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    }
  }
}));
```

