// Secure Express.js application with comprehensive error handling and input validation

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const dotenv = require('dotenv');

// Load environment variables with validation
dotenv.config({ path: process.env.NODE_ENV === 'test' ? '.env.test' : '.env' });

// Validate required environment variables
const requiredEnvVars = ['PORT'];
const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);
if (missingVars.length > 0) {
  throw new Error(`Missing required environment variables: ${missingVars.join(', ')}`);
}

const app = express();

// Security Middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
}));

app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateInput = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array(),
      message: 'Invalid input data'
    });
  }
  next();
};

// Centralized error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip
  });

  // Don't expose internal error details in production
  const errorResponse = {
    success: false,
    message: process.env.NODE_ENV === 'production' 
      ? 'Something went wrong' 
      : err.message
  };

  // Handle specific error types
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      ...errorResponse,
      message: 'Validation failed',
      errors: err.details || []
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      ...errorResponse,
      message: 'Unauthorized access'
    });
  }

  // Default to 500 internal server error
  res.status(err.status || 500).json(errorResponse);
};

// Health check endpoint with validation
app.get('/health', [
  // Query parameter validation if needed
], validateInput, (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    throw new Error('Health check failed');
  }
});

// Users endpoint with comprehensive validation
app.get('/users', [
  // Query parameter validation
  body('page').optional().isInt({ min: 1, max: 100 }).withMessage('Page must be between 1 and 100'),
  body('limit').optional().isInt({ min: 1, max: 50 }).withMessage('Limit must be between 1 and 50'),
], validateInput, async (req, res, next) => {
  try {
    const { page = 1, limit = 10 } = req.query;

    // Validate and sanitize inputs
    const validatedPage = Math.max(1, parseInt(page) || 1);
    const validatedLimit = Math.min(50, Math.max(1, parseInt(limit) || 10));

    // Simulate database query - in real app, this would be a proper database call
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        createdAt: new Date().toISOString()
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        createdAt: new Date().toISOString()
      },
    ];

    // Apply pagination (simplified)
    const startIndex = (validatedPage - 1) * validatedLimit;
    const paginatedUsers = users.slice(startIndex, startIndex + validatedLimit);

    res.json({
      success: true,
      data: paginatedUsers,
      pagination: {
        page: validatedPage,
        limit: validatedLimit,
        total: users.length,
        totalPages: Math.ceil(users.length / validatedLimit)
      }
    });
  } catch (error) {
    next(error); // Pass error to centralized error handler
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    success: false,
    message: 'Route not found',
    path: req.originalUrl
  });
});

// Apply error handling middleware last
app.use(errorHandler);

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running securely on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

