// Secure minimal version of app.js with essential security improvements
const express = require('express');

const app = express();

// Basic security middleware
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// Basic request size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Simple input validation middleware
const validateQueryParams = (req, res, next) => {
  if (req.query) {
    // Basic validation for numeric parameters
    const numericParams = ['limit', 'offset', 'page'];
    for (const param of numericParams) {
      if (req.query[param] && !/^\d+$/.test(req.query[param])) {
        return res.status(400).json({
          error: 'Invalid parameter',
          message: `${param} must be a positive integer`
        });
      }
    }
  }
  next();
};

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err.message);
  res.status(500).json({
    error: 'Internal Server Error',
    message: 'Something went wrong. Please try again later.'
  });
});

// Health endpoint with basic validation
app.get('/health', validateQueryParams, (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Users endpoint with input validation
app.get('/users', validateQueryParams, (req, res, next) => {
  try {
    // Validate and parse limit/offset parameters
    const limit = req.query.limit ? Math.min(parseInt(req.query.limit), 100) : 10;
    const offset = req.query.offset ? parseInt(req.query.offset) : 0;

    if (limit < 1 || offset < 0) {
      return res.status(400).json({
        error: 'Invalid parameters',
        message: 'Limit must be at least 1 and offset must be non-negative'
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply basic pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: users.length,
