// Enhanced Express application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const expressValidator = require('express-validator');
const morgan = require('morgan');
const app = express();

// Environment variables
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Security Middleware
app.use(helmet()); // Sets various security headers

// Request logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation/sanitization middleware
app.use(expressValidator());

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak error details in production
  const errorMessage = NODE_ENV === 'production' 
    ? 'Something went wrong!' 
    : err.message;

  res.status(500).json({
    error: errorMessage,
    status: 'error'
  });
});

// Health endpoint with improved validation
app.get('/health', (req, res, next) => {
  try {
    // Validate query parameters if any
    req.checkQuery('detailed', 'Invalid detailed parameter').optional().isBoolean();

    const errors = req.validationErrors();
    if (errors) {
      return res.status(400).json({
        error: 'Invalid parameters',
        details: errors,
        status: 'error'
      });
    }

    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: NODE_ENV
    };

    if (req.query.detailed === 'true') {
      healthData.memory = process.memoryUsage();
      healthData.nodeVersion = process.version;
    }

    res.json(healthData);
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Users endpoint with validation and error handling
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters
    req.checkQuery('limit', 'Limit must be a number between 1 and 100')
      .optional().isInt({ min: 1, max: 100 });
    req.checkQuery('offset', 'Offset must be a non-negative number')
      .optional().isInt({ min: 0 });

    const errors = req.validationErrors();
    if (errors) {
      return res.status(400).json({
        error: 'Invalid parameters',
        details: errors,
        status: 'error'
      });
    }

    // Mock database call with error simulation
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simulate potential database error (for demonstration)
    if (req.query.simulateError === 'true') {
      throw new Error('Database connection failed');
    }

    // Apply pagination if requested
    const limit = parseInt(req.query.limit) || mockUsers.length;
    const offset = parseInt(req.query.offset) || 0;

    const paginatedUsers = mockUsers.slice(offset, offset + limit);

    res.json({
      users: paginatedUsers,
      total: mockUsers.length,
      limit,
      offset
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    status: 'error',
    requestedUrl: req.originalUrl
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

// Start server with error handling
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
}).on('error', (err) => {
  if (err.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
  } else {
    console.error('Server error:', err);
  }
  process.exit(1);
});

module.exports = { app, server };

